def scan_feeds(top_n=20):
    feeds = load_feeds()
    all_episodes = []

    for feed_info in feeds:
        print(f"抓取: {feed_info['name']}...")
        feed = feedparser.parse(feed_info["url"])
        for entry in feed.entries[:10]:
            title = entry.get("title", "")
            summary = entry.get("summary", entry.get("description", ""))
            all_episodes.append({
                "feed": feed_info["name"],
                "title": title,
                "summary": summary[:300],
                "link": entry.get("link", ""),
                "audio": extract_audio_url(entry),
            })

    # 分批让LLM打分（每批20条避免prompt过长）
    print(f"\n共抓取 {len(all_episodes)} 集，调用LLM评分中...")
    scored = []
    batch_size = 20
    for i in range(0, len(all_episodes), batch_size):
        batch = all_episodes[i:i+batch_size]
        scores = score_episodes_with_llm(batch)
        for s in scores:
            idx = s.get("index", 0)
            if 0 <= idx < len(batch) and s.get("score", 0) >= 5:
                ep = batch[idx]
                ep["score"] = s["score"]
                ep["reason"] = s.get("reason", "")
                scored.append(ep)

    scored.sort(key=lambda x: x["score"], reverse=True)
    scored = scored[:top_n]

    # 输出推荐列表
    print(f"\n{'='*60}")
    print(f"推荐单集 (共 {len(scored)} 集，按相关度排序)")
    print(f"{'='*60}\n")
    for i, ep in enumerate(scored, 1):
        print(f"[{i}] [{ep['feed']}] {ep['title']}")
        print(f"    评分: {ep['score']}/10  理由: {ep['reason']}")
        print(f"    链接: {ep['link']}")
        print()

    # 保存推荐结果
    rec_file = Path(__file__).parent / "recommendations.json"
    rec_file.write_text(json.dumps(scored, ensure_ascii=False, indent=2))
    print(f"推荐列表已保存到 {rec_file}")


def extract_audio_url(entry):
    """Extract audio/video URL from RSS entry enclosures."""
    for enc in entry.get("enclosures", []):
        if "audio" in enc.get("type", "") or "video" in enc.get("type", ""):
            return enc.get("href", "")
    # fallback: links
    for link in entry.get("links", []):
        if "audio" in link.get("type", "") or "video" in link.get("type", ""):
            return link.get("href", "")
    return entry.get("link", "")


