def download_audio(url, output_dir):
    """Download audio using yt-dlp (handles YouTube, podcasts, direct URLs)."""
    output_path = os.path.join(output_dir, "audio.%(ext)s")
    cmd = [
        "yt-dlp", "-x", "--audio-format", "mp3",
        "-o", output_path, url
    ]
    print(f"下载音频: {url}")
    subprocess.run(cmd, check=True)
    # find the downloaded file
    for f in os.listdir(output_dir):
        if f.startswith("audio"):
            return os.path.join(output_dir, f)
    raise FileNotFoundError("下载失败")

def transcribe_audio(audio_path, model="base"):
    """Transcribe using Whisper."""
    import whisper
    print(f"转录中 (模型: {model})...")
    m = whisper.load_model(model)
    result = m.transcribe(audio_path, verbose=False)
    return result


def format_timestamp(seconds):
    h = int(seconds // 3600)
    m = int((seconds % 3600) // 60)
    s = int(seconds % 60)
    if h > 0:
        return f"{h:02d}:{m:02d}:{s:02d}"
    return f"{m:02d}:{s:02d}"


def build_raw_transcript(result):
    """Build timestamped transcript text."""
    lines = []
    for seg in result["segments"]:
        ts = format_timestamp(seg["start"])
        lines.append(f"[{ts}] {seg['text'].strip()}")
    return "\n".join(lines)


