"""Podcast Tool - RSS fetch, web scrape, audio transcribe, article fetch utilities."""

import argparse
import json
import os
import re
import subprocess
import sys
import tempfile
import urllib.request
from html.parser import HTMLParser
from pathlib import Path

import feedparser

NOTES_DIR = Path(__file__).parent.parent / "notes"
NOTES_DIR.mkdir(exist_ok=True)
FEEDS_FILE = Path(__file__).parent.parent / "references" / "feeds.json"

HEADERS = {"User-Agent": "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36"}


# ─── HTML LINK EXTRACTOR ────────────────────────────────────────────────────

class LinkExtractor(HTMLParser):
    """Extract article links and titles from blog listing pages."""

    def __init__(self, base_url, selectors=None):
        super().__init__()
        self.base_url = base_url.rstrip("/")
        self.articles = []
        self.current_href = None
        self.current_text = ""
